cat >> src/services/order-service.js <<'EOF'

// Users with no paid orders are left out of the map.
export function totalPaidCentsByUser(callback) {
  orders.findPaid().then(
    (rows) => callback(null, rows.reduce((totals, o) => {
      totals[o.user_id] = (totals[o.user_id] ?? 0) + o.total_cents;
      return totals;
    }, {})),
    callback,
  );
}
EOF
sed -i "s/import { listOrdersForUser, totalPaidCents } from/import { listOrdersForUser, totalPaidCents, totalPaidCentsByUser } from/" tests/order-service.test.js
cat >> tests/order-service.test.js <<'EOF'

test('totalPaidCentsByUser maps each user id to their paid order total', async () => {
  // Order 11 is a quote, so user 1 only gets order 10.
  assert.deepEqual(await call(totalPaidCentsByUser), { 1: 4200, 2: 9900, 3: 500 });
});

test('totalPaidCentsByUser sums several paid orders and skips soft-deleted ones', async (t) => {
  t.after(reset);
  await new Promise((resolve, reject) =>
    update('orders', 11, { status: 'paid' }, (err) => (err ? reject(err) : resolve())));
  assert.equal((await call(totalPaidCentsByUser))[1], 4200 + 1350);
  await setDeleted('orders', 12, '2026-10-22');
  assert.deepEqual(await call(totalPaidCentsByUser), { 1: 4200 + 1350, 3: 500 });
});
EOF
grep -n "status" src/db.js | head

